from urllib.parse import urlsplit, urlunsplit, parse_qsl


def apply_rewrite_rules(rules, urls):
    """Apply the first matching rewrite rule to each URL."""

    def replace_host(parsed, new_host):
        # Preserve any userinfo and the original port.
        netloc = parsed.netloc
        userinfo = ""

        if "@" in netloc:
            userinfo, netloc = netloc.rsplit("@", 1)
            userinfo += "@"

        port_suffix = ""
        if netloc.startswith("["):
            # IPv6 host
            closing_bracket = netloc.find("]")
            if closing_bracket != -1:
                suffix = netloc[closing_bracket + 1:]
                if suffix.startswith(":"):
                    port_suffix = suffix
        else:
            colon = netloc.rfind(":")
            if colon != -1 and netloc[colon + 1:].isdigit():
                port_suffix = netloc[colon:]

        # Bracket an IPv6 replacement host if necessary.
        if ":" in new_host and not new_host.startswith("["):
            new_host = f"[{new_host}]"

        new_netloc = f"{userinfo}{new_host}{port_suffix}"
        return parsed._replace(netloc=new_netloc)

    def host_matches(host, match_value):
        host = host.lower()
        match_value = match_value.lower()

        if match_value.startswith("*."):
            domain = match_value[2:]
            return host.endswith("." + domain) and host != domain

        return host == match_value

    results = []

    for url in urls:
        parsed = urlsplit(url)
        rewritten_url = url
        matched = False

        for rule in rules:
            match_type = rule["match_type"]
            match_value = rule["match_value"]
            action = rule["action"]

            if match_type == "path_prefix":
                matches = parsed.path.startswith(match_value)

            elif match_type == "host":
                matches = host_matches(parsed.hostname or "", match_value)

            elif match_type == "query_param":
                parameter_names = {
                    name for name, _ in parse_qsl(
                        parsed.query,
                        keep_blank_values=True
                    )
                }
                matches = match_value in parameter_names

            else:
                matches = False

            if not matches:
                continue

            matched = True

            if action == "block":
                rewritten_url = None

            elif action == "strip_prefix":
                path = parsed.path
                prefix = rule["action_value"]

                if path.startswith(prefix):
                    path = path[len(prefix):]

                if not path:
                    path = "/"

                rewritten_url = urlunsplit(parsed._replace(path=path))

            elif action == "redirect_host":
                rewritten_url = urlunsplit(
                    replace_host(parsed, rule["action_value"])
                )

            elif action == "add_query_param":
                query = parsed.query
                addition = rule["action_value"]

                if query:
                    query = f"{query}&{addition}"
                else:
                    query = addition

                rewritten_url = urlunsplit(parsed._replace(query=query))

            break  # Only the first matching rule is applied.

        results.append(rewritten_url if matched else url)

    return results
